public class QL {
 public String names(List<SObject> rows) {
  List<String> values=new List<String>();
  for(SObject row:rows) values.add(String.valueOf(row.get('Name')));
  return String.join(values,'|');
 }
 public String walk(Database.QueryLocator q) {
  List<SObject> rows=new List<SObject>();
  Database.QueryLocatorIterator it=q.iterator();
  while(it.hasNext()) rows.add(it.next());
  return names(rows);
 }
}

